  const scope8Basis = (over) => Object.assign({ basisId: 'b', companyId: 'peer', concept: 'revenue', unit: 'USD', currency: 'USD', fiscalYearEnd: '12-31', periodId: 'p', periodEnd: '2025-12-31', value: '100' }, over);
